const actionForm=document.querySelector('#action-form'),actionMessage=document.querySelector('#action-feedback');let actionRows=[];
async function actionList(){try{const r=await fetch('/api/admin/acoes');if(!r.ok)throw Error('Não foi possível consultar as ações.');actionRows=(await r.json()).items;const select=document.querySelector('#action-existing');select.replaceChildren(new Option('Nova ação',''));for(const a of actionRows)select.add(new Option(a.titulo+' · '+(a.publicada?'Publicada':'Rascunho'),a.id));}catch(e){actionMessage.textContent=e.message;}}
document.querySelector('#action-existing').onchange=e=>{const a=actionRows.find(x=>x.id===e.target.value);actionForm.reset();if(a)for(const key of ['id','titulo','resumo','conteudo','data_realizacao'])actionForm.elements[key].value=a[key];};
actionForm.onsubmit=async e=>{e.preventDefault();if(!actionForm.reportValidity())return;const published=e.submitter?.value==='publicar';const f=new FormData(actionForm);const data={id:f.get('id')||undefined,titulo:f.get('titulo'),resumo:f.get('resumo'),conteudo:f.get('conteudo'),data_realizacao:f.get('data_realizacao'),publicada:published};const buttons=[...actionForm.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const response=await fetch('/api/admin/acoes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw Error(result.error);actionForm.elements.id.value=result.id;actionMessage.textContent=published?'Ação publicada no dashboard e incluída na contagem do mês.':'Rascunho salvo. A ação não aparece para o público.';await actionList();window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{periodo:data.data_realizacao.slice(0,7)}}));document.querySelector('#action-existing').value=result.id;}catch(error){actionMessage.textContent=error.message;}finally{buttons.forEach(b=>b.disabled=false);}};actionForm.elements.data_realizacao.max=new Date().toISOString().slice(0,10);actionList();
